import json, os, openpyxl
mf = json.load(open('inputs/manifest.json'))
paths = []
def walk(o):
    if isinstance(o, dict):
        for v in o.values(): walk(v)
    elif isinstance(o, list):
        for v in o: walk(v)
    elif isinstance(o, str) and o.lower().endswith(('.xlsx', '.xlsm')):
        paths.append(o)
walk(mf)
print('PATHS', paths[:5])
cands = []
for p in paths:
    for q in (p, os.path.join('inputs', p), os.path.join('.', p)):
        if os.path.exists(q) and q not in cands:
            cands.append(q)
print('CANDS', cands[:3])
p = cands[0]
wf = openpyxl.load_workbook(p, data_only=False)
wv = openpyxl.load_workbook(p, data_only=True)
for ws in wf.worksheets:
    vs = wv[ws.title]
    print('SHEET', ws.title, 'dims', ws.max_row, ws.max_column)
    rows = list(range(1, min(ws.max_row, 4) + 1))
    if ws.max_row > 5:
        rows += [ws.max_row - 1, ws.max_row]
    for r in rows:
        cells = []
        for c in range(1, min(ws.max_column, 3) + 1):
            a = ws.cell(r, c); b = vs.cell(r, c)
            cells.append((a.coordinate, a.data_type, a.number_format, repr(a.value)[:70], repr(b.value)[:25]))
        print(cells)

